(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[99,357],{6797:(e,a,t)=>{"use strict";t.d(a,{default:()=>r});var i=t(5155),n=t(2115),o=t(7995);function r(e){let{kind:a}=e,[t,r]=(0,n.useState)("en");(0,n.useEffect)(()=>{let e=new URLSearchParams(window.location.search).get("lang");"en"===e||"zh-Hans"===e||"zh-Hant"===e?r(e):navigator.language.toLowerCase().startsWith("zh")&&r(/hant|tw|hk|mo/i.test(navigator.language)?"zh-Hant":"zh-Hans")},[]);let s=o[t];return(0,i.jsx)("main",{lang:t,className:"min-h-screen bg-[#faf6f1] px-5 py-10 text-[#342a24]",children:(0,i.jsxs)("article",{className:"mx-auto max-w-3xl rounded-2xl bg-white p-6 shadow-sm sm:p-10",children:[(0,i.jsxs)("header",{className:"mb-7 flex flex-wrap items-center justify-between gap-4",children:[(0,i.jsx)("a",{href:"https://ideaspike.com",className:"font-semibold text-[#995018]",children:"Final Curtain"}),(0,i.jsxs)("label",{children:[(0,i.jsx)("span",{className:"sr-only",children:"Language / 语言 / 語言"}),(0,i.jsxs)("select",{value:t,onChange:e=>r(e.target.value),className:"rounded-lg border border-gray-300 bg-white px-3 py-2",children:[(0,i.jsx)("option",{value:"en",children:"English"}),(0,i.jsx)("option",{value:"zh-Hans",children:"简体中文"}),(0,i.jsx)("option",{value:"zh-Hant",children:"繁體中文"})]})]})]}),(0,i.jsx)("h1",{className:"mb-3 text-3xl font-bold",children:"privacy"===a?s.privacyTitle:s.termsTitle}),(0,i.jsx)("p",{className:"mb-8 text-sm text-gray-600",children:s.updated}),s[a].map(e=>{let[a,t]=e;return(0,i.jsxs)("section",{className:"mb-7 leading-7",children:[(0,i.jsx)("h2",{className:"mb-2 text-xl font-semibold",children:a}),(0,i.jsx)("p",{children:t})]},a)}),(0,i.jsxs)("footer",{className:"border-t border-gray-200 pt-5 text-sm",children:[(0,i.jsxs)("nav",{className:"mb-4 flex flex-wrap gap-5",children:[(0,i.jsx)("a",{className:"text-[#995018] underline",href:"/final-curtain/privacy/?lang=".concat(t),children:s.privacyTitle}),(0,i.jsx)("a",{className:"text-[#995018] underline",href:"/final-curtain/tos/?lang=".concat(t),children:s.termsTitle})]}),"IDEASpike \xb7 ",s.contact,": ",(0,i.jsx)("a",{className:"text-[#995018] underline",href:"mailto:support@ideaspike.com",children:"support@ideaspike.com"})]})]})})}},7995:e=>{"use strict";e.exports=JSON.parse('{"en":{"updated":"Updated October 12, 2026","privacyTitle":"Privacy Policy","termsTitle":"Terms of Service","contact":"Contact","privacy":[["What Final Curtain does","Final Curtain is a local time-reflection app. It estimates remaining time from a birth date and a horizon you choose, and lets you explore recurring activities, large time blocks, reserves and separate profiles. It does not predict lifespan."],["Information on your device","Birth dates, profile names, chosen horizons, activity names and amounts, retirement or graduation assumptions, and block/reserve settings are stored on the current device. The selected horizon is shared locally with the widget through an Apple App Group. The app has no separate app account, custom backend or app-provided cloud synchronization."],["Optional on-device AI","On supported devices with Apple Intelligence enabled, a summary can use Apple’s on-device Foundation Models. Allocation data is processed on the device and is not sent to IDEASpike or a cloud AI provider. Generated text can be incomplete or inaccurate and is not a diagnosis or prediction."],["Apple purchases and services","Apple processes the optional Final Curtain Pro purchase. StoreKit provides product and purchase-entitlement information so the app can unlock Pro and recognize an eligible legacy widget purchase; we do not receive payment-card details. Apple’s App Store, TestFlight and device services operate under Apple’s own policies. Feedback that you voluntarily send through TestFlight may be visible to IDEASpike."],["Storage and your choices","You can remove activities, clear a list, edit assumptions and delete additional profiles in the app. At least one profile remains. Removing the app removes its app-local files; device backups may retain copies according to your Apple/device backup settings. We do not provide cross-device recovery or remote deletion of your backups."],["Website and contact","Opening legal or reference links contacts the destination website. Hosting providers receive ordinary web-request information such as IP addresses. Information you choose to email to support is used to respond to your request. The app does not include advertising or developer-added tracking/analytics SDKs."],["Changes and assistance","We update this page when processing changes. For questions or assistance, contact support@ideaspike.com. This policy applies to Final Curtain; other IDEASpike apps have their own policies."]],"terms":[["Purpose and estimates","Final Curtain helps you reflect on finite time and compare choices. Birth date, life horizon, rates, block durations and end dates are assumptions you control. Estimates are not predictions, commitments or guarantees that you will complete any activity."],["Your choices","You decide what matters, whether to change an allocation, and whether to follow any suggestion. Example amounts and population averages are not personal targets. Large blocks replace routine time from today; needs inside those periods are included. References explain comparisons, not an optimal life plan."],["AI and health","Optional on-device summaries can be incomplete or inaccurate. The app does not provide medical, financial or other professional advice, diagnose a person, or determine their worth. For sleep or health concerns, consult an appropriate professional rather than relying on allocation arithmetic."],["Purchases","Final Curtain Pro unlocks Compare Choices and the Home Screen widget through a one-time non-consumable Apple purchase, rather than a subscription. An eligible verified legacy widget purchase also grants Pro access. Apple displays the current offer and price and handles payment. Restoration depends on the applicable Apple Account and a valid StoreKit entitlement; refunded or revoked entitlements may no longer unlock Pro. Restoring a purchase does not restore deleted local planning data. Refund requests follow Apple’s process and applicable law; these terms do not limit mandatory consumer rights."],["Local data","Keep device access secure and consider your backup settings. Profiles stay on the current device and are not app accounts. Single-activity deletion occurs immediately, including a full swipe; clearing the list and deleting a profile require confirmation. We do not guarantee recovery of removed local data."],["Licence and intellectual property","Your right to use Final Curtain is also subject to the Apple end-user licence agreement that applies to your download; where no custom EULA applies, Apple’s Standard EULA applies. Subject to that agreement and these terms, IDEASpike grants you a limited, personal and non-transferable licence to use the app for its intended purpose. IDEASpike and its licensors retain all rights in the app, software, design and supplied content."],["Use and availability","Use the app lawfully and respect other people’s privacy when entering their information. IDEASpike may update, suspend or discontinue features. To the extent permitted by law, the app is provided as available without additional warranties beyond those expressly stated in these terms or required by law, and IDEASpike is not liable for indirect or consequential loss arising from reliance on estimates, generated reflections or service interruption. Nothing in these terms excludes liability or consumer rights that cannot be excluded under applicable law."],["Updates and contact","Updated terms appear on this page. Contact support@ideaspike.com for app questions or purchase assistance."]]},"zh-Hans":{"updated":"更新于 2026 年 10 月 12 日","privacyTitle":"隐私政策","termsTitle":"使用条款","contact":"联系","privacy":[["应用提供什么","Final Curtain 是本地时间反思应用。它依据生日和你选择的人生期限估算剩余时间，帮助你探索日常活动、大块时间、预留余量及不同档案。它不会预测寿命。"],["本设备上的信息","生日、档案名称、人生期限、活动名称和时间量、退休或毕业假设及大块时间与预留设置保存在当前设备。所选期限通过 Apple App Group 在本设备与小组件共享。应用没有独立登录账户、自建后台或应用提供的云同步。"],["可选的设备端 AI","在支持 Apple Intelligence 且已启用的设备上，总结可使用 Apple 设备端 Foundation Models。活动分配数据只在设备上处理，不会发送给 IDEASpike 或云端 AI 服务商。生成内容可能不完整或不准确，不是诊断或预测。"],["Apple 购买与服务","Apple 处理可选的 Final Curtain Pro 购买。StoreKit 提供商品与购买权益信息，供应用解锁 Pro 并识别符合条件的旧版小组件购买；我们不接收银行卡资料。App Store、TestFlight 和设备服务适用 Apple 自己的政策。你主动通过 TestFlight 发送的反馈可能由 IDEASpike 查看。"],["保存期限与选择","你可删除活动、清空清单、修改假设及删除多余档案。至少保留一个档案。删除应用会删除其本地文件；Apple 或设备备份可能依照你的备份设置保留副本。我们不提供跨设备恢复，也不能远程删除你的备份。"],["网站与联系","打开法律或参考链接会连接到目标网站，托管服务会收到 IP 地址等常规请求信息。你主动发送给支持邮箱的信息用于回复请求。应用不包含广告或开发者添加的跟踪、分析 SDK。"],["更新与协助","处理方式改变时会更新本页。有问题可联系 support@ideaspike.com。本政策适用于 Final Curtain，其他 IDEASpike 应用有各自政策。"]],"terms":[["用途与估算","Final Curtain 帮助你认识有限时间并比较选择。生日、人生期限、时间量、大块活动时长和结束期限均是你控制的假设。结果不是预测、承诺或完成活动的保证。"],["你的选择","什么重要、是否调整时间及是否采纳建议，均由你决定。示例数值和群体平均值不是个人目标。大块时间从今天起替代日常时间，期间的生活需要已包含在内。参考资料用于解释比较，并不代表最优人生方案。"],["AI 与健康","可选的设备端总结可能不完整或不准确。应用不提供医疗、财务等专业建议，不诊断个人，也不衡量个人价值。睡眠或健康问题应咨询相应专业人士，而非依赖时间分配计算。"],["购买","Final Curtain Pro 通过 Apple 的一次性非消耗型购买解锁“比较选择”和主屏幕小组件，无需订阅。符合条件且已验证的旧版小组件购买也可获得 Pro 权益。Apple 显示当前商品与价格并处理付款。恢复购买依赖相应 Apple 账户及有效的 StoreKit 权益；已退款或撤销的权益可能不再解锁 Pro。恢复购买不会恢复已删除的本地规划数据。退款遵循 Apple 流程和适用法律；这些条款不限制强制性消费者权利。"],["本地数据","请保护设备访问安全并了解备份设置。档案只保存在当前设备，不是应用账户。单项活动会立即删除，包括完整左滑；清空清单和删除档案仍需确认。我们不保证恢复已删除的本地数据。"],["许可与知识产权","你使用 Final Curtain 的权利也受适用于该下载的 Apple 最终用户许可协议约束；如没有适用的自定义许可协议，则适用 Apple 标准最终用户许可协议。在该协议和本条款约束下，IDEASpike 授予你仅为预定用途使用本应用的有限、个人且不可转让许可。应用、软件、设计及所提供内容的全部权利由 IDEASpike 及其许可方保留。"],["使用与可用性","请合法使用应用，录入他人信息时尊重其隐私。IDEASpike 可更新、暂停或停止功能。在法律允许的范围内，应用按可用状态提供，除本条款明确约定或法律要求外，不作出额外保证；对于依赖估算、生成的反思文字或服务中断造成的间接或后果性损失，IDEASpike 不承担责任。本条款不排除依法不得排除的责任或消费者权利。"],["更新与联系","更新条款会在本页发布。应用问题或购买协助可联系 support@ideaspike.com。"]]},"zh-Hant":{"updated":"更新於 2026 年 10 月 12 日","privacyTitle":"隱私政策","termsTitle":"使用條款","contact":"聯絡","privacy":[["App 提供什麼","Final Curtain 是本機時間反思 App。它依據生日和你選擇的人生期限估算剩餘時間，協助你探索日常活動、大段時間、預留餘量及不同檔案。它不會預測壽命。"],["本裝置上的資訊","生日、檔案名稱、人生期限、活動名稱和時間量、退休或畢業假設及大段時間與預留設定保存在目前裝置。所選期限透過 Apple App Group 在本裝置與小工具共享。App 沒有獨立登入帳號、自建後台或 App 提供的雲端同步。"],["可選的裝置端 AI","在支援 Apple Intelligence 且已啟用的裝置上，總結可使用 Apple 裝置端 Foundation Models。活動分配資料只在裝置上處理，不會傳送給 IDEASpike 或雲端 AI 服務商。產生內容可能不完整或不準確，不是診斷或預測。"],["Apple 購買與服務","Apple 處理可選的 Final Curtain Pro 購買。StoreKit 提供商品與購買權益資訊，供 App 解鎖 Pro 並識別符合條件的舊版小工具購買；我們不接收銀行卡資料。App Store、TestFlight 和裝置服務適用 Apple 自己的政策。你主動透過 TestFlight 傳送的回饋可能由 IDEASpike 查看。"],["保存期限與選擇","你可刪除活動、清空清單、修改假設及刪除多餘檔案。至少保留一個檔案。刪除 App 會刪除其本機檔案；Apple 或裝置備份可能依照你的備份設定保留副本。我們不提供跨裝置復原，也不能遠端刪除你的備份。"],["網站與聯絡","開啟法律或參考連結會連接目標網站，託管服務會收到 IP 位址等一般請求資訊。你主動傳送給支援信箱的資訊用於回覆請求。App 不包含廣告或開發者新增的追蹤、分析 SDK。"],["更新與協助","處理方式改變時會更新本頁。有問題可聯絡 support@ideaspike.com。本政策適用於 Final Curtain，其他 IDEASpike App 有各自政策。"]],"terms":[["用途與估算","Final Curtain 協助你認識有限時間並比較選擇。生日、人生期限、時間量、大段活動時長和結束期限均是你控制的假設。結果不是預測、承諾或完成活動的保證。"],["你的選擇","什麼重要、是否調整時間及是否採納建議，均由你決定。範例數值和群體平均值不是個人目標。大段時間從今天起取代日常時間，期間的生活需要已包含在內。參考資料用於解釋比較，並不代表最優人生方案。"],["AI 與健康","可選的裝置端總結可能不完整或不準確。App 不提供醫療、財務等專業建議，不診斷個人，也不衡量個人價值。睡眠或健康問題應諮詢相應專業人士，而非依賴時間分配計算。"],["購買","Final Curtain Pro 透過 Apple 的一次性非消耗型購買解鎖「比較選擇」和主畫面小工具，無需訂閱。符合條件且已驗證的舊版小工具購買也可取得 Pro 權益。Apple 顯示目前商品與價格並處理付款。復原購買依賴相應 Apple 帳號及有效的 StoreKit 權益；已退款或撤銷的權益可能不再解鎖 Pro。復原購買不會復原已刪除的本機規劃資料。退款遵循 Apple 流程和適用法律；這些條款不限制強制性消費者權利。"],["本機資料","請保護裝置存取安全並了解備份設定。檔案只保存在目前裝置，不是 App 帳號。單項活動會立即刪除，包括完整左滑；清空清單和刪除檔案仍需確認。我們不保證復原已刪除的本機資料。"],["授權與智慧財產權","你使用 Final Curtain 的權利也受適用於該下載的 Apple 最終使用者授權協議約束；如沒有適用的自訂授權協議，則適用 Apple 標準最終使用者授權協議。在該協議及本條款約束下，IDEASpike 授予你僅為預定用途使用本 App 的有限、個人且不可轉讓授權。App、軟體、設計及所提供內容的全部權利由 IDEASpike 及其授權方保留。"],["使用與可用性","請合法使用 App，輸入他人資訊時尊重其隱私。IDEASpike 可更新、暫停或停止功能。在法律允許的範圍內，App 按可用狀態提供，除本條款明確約定或法律要求外，不作出額外保證；對於依賴估算、產生的反思文字或服務中斷造成的間接或後果性損失，IDEASpike 不承擔責任。本條款不排除依法不得排除的責任或消費者權利。"],["更新與聯絡","更新條款會在本頁發布。App 問題或購買協助可聯絡 support@ideaspike.com。"]]}}')},8341:(e,a,t)=>{Promise.resolve().then(t.bind(t,6797))}},e=>{var a=a=>e(e.s=a);e.O(0,[441,684,358],()=>a(8341)),_N_E=e.O()}]);